		CompensationPackage parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Contract on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Contract on the parent entithy
		// ------------------------------------------     
	    parentEntity.setContract(null);

